import { Injectable, signal } from '@angular/core';

export interface Message { id: number; text: string; style: 'success' | 'error'; }

@Injectable({ providedIn: 'root' })
export class Messages {
  private seq = 0;
  readonly messages = signal<Message[]>([]);
  success(text: string): void { this.add(text, 'success'); }
  error(text: string): void { this.add(text, 'error'); }
  private add(text: string, style: 'success' | 'error'): void {
    const m: Message = { id: ++this.seq, text, style };
    // Only one message per style at a time so the debug id stays unique.
    this.messages.update(list => [...list.filter(x => x.style !== style), m]);
  }
  close(id: number): void { this.messages.update(list => list.filter(x => x.id !== id)); }
}
