import { Component, OnInit, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { Api, CarDto, RatingDto, carLabel } from './api';
import { Messages } from './messages';

@Component({
  selector: 'app-rating',
  standalone: true,
  imports: [FormsModule],
  template: `
    <h2>Ratings</h2>
    <button id="gwt-debug-ratingCreate" (click)="create()">Create</button>
    <table id="gwt-debug-ratings" class="grid">
      <thead><tr><th>ID</th><th>Car</th><th>Rating</th><th>Delete</th></tr></thead>
      <tbody>
        @for (r of ratings(); track r.id) {
          <tr>
            <td>{{ r.id }}</td>
            <td>{{ label(r.car) }}</td>
            <td>{{ r.rating }}</td>
            <td><button (click)="remove(r)">Delete</button></td>
          </tr>
        }
      </tbody>
    </table>
    @if (creating()) {
      <div class="glass" (click)="creating.set(false)"></div>
      <div class="popup">
        <div>
          <span>Car:</span>
          <select [(ngModel)]="carIndex">
            @for (c of cars(); track $index) {
              <option [ngValue]="$index">{{ label(c) }}</option>
            }
          </select>
        </div>
        <div>
          <span>Your rating:</span>
          <input id="gwt-debug-ratingInput" type="text" maxlength="3" [(ngModel)]="ratingText" />
        </div>
        <div>
          <button id="gwt-debug-ratingSave" (click)="save()">Save</button>
          <button (click)="creating.set(false)">Close</button>
        </div>
      </div>
    }
  `,
})
export class RatingComponent implements OnInit {
  private api = inject(Api);
  private messages = inject(Messages);
  ratings = signal<RatingDto[]>([]);
  cars = signal<CarDto[]>([]);
  creating = signal(false);
  carIndex = 0;
  ratingText = '';
  label = carLabel;

  ngOnInit(): void {
    this.api.getRatings().subscribe({
      next: l => this.ratings.set(l ?? []),
      error: () => this.messages.error('Error retrieving ratings'),
    });
  }

  create(): void {
    this.carIndex = 0;
    this.ratingText = '';
    this.creating.set(true);
    this.api.getCars().subscribe({
      next: l => this.cars.set(l ?? []),
      error: () => this.messages.error('Error retrieving cars'),
    });
  }

  save(): void {
    const car = this.cars()[this.carIndex] ?? null;
    const value = parseInt(this.ratingText, 10);
    if (!car || isNaN(value)) {
      this.messages.error('Please choose a car and enter a valid rating');
      return;
    }
    this.api.saveRating({ car, rating: value }).subscribe({
      next: saved => {
        this.creating.set(false);
        this.ratings.update(l => [...l, saved]);
        this.messages.success('Rating saved');
      },
      error: () => this.messages.error('Error saving rating'),
    });
  }

  remove(r: RatingDto): void {
    if (!window.confirm('Are you sure you want to delete this rating?')) { return; }
    this.api.deleteRating(r.id as number).subscribe({
      next: () => {
        this.ratings.update(l => l.filter(x => x.id !== r.id));
        this.messages.success('Rating deleted');
      },
      error: () => this.messages.error('Error deleting rating'),
    });
  }
}
