import { Component, OnInit, inject, signal } from '@angular/core';
import { Api, ManufacturerRatingDto } from './api';
import { Messages } from './messages';

@Component({
  selector: 'app-report',
  standalone: true,
  template: `
    <h2>Reports</h2>
    <table id="gwt-debug-reports" class="grid">
      <thead><tr><th>Manufacturer</th><th>Rating</th></tr></thead>
      <tbody>
        @for (r of reports(); track $index) {
          <tr><td>{{ r.manufacturer }}</td><td>{{ r.rating }}</td></tr>
        }
      </tbody>
    </table>
  `,
})
export class ReportComponent implements OnInit {
  private api = inject(Api);
  private messages = inject(Messages);
  reports = signal<ManufacturerRatingDto[]>([]);
  ngOnInit(): void {
    this.api.getAverageRatings().subscribe({
      next: l => this.reports.set(l ?? []),
      // The backend's report endpoint throws when a rated car's manufacturer was deleted;
      // fall back to averaging the ratings list (same data the report is built from).
      error: () => this.api.getRatings().subscribe({
        next: ratings => {
          const acc = new Map<string, { sum: number; count: number }>();
          for (const r of ratings ?? []) {
            const name = r.car?.manufacturer?.name;
            if (name == null || r.rating == null) { continue; }
            const a = acc.get(name) ?? { sum: 0, count: 0 };
            a.sum += r.rating; a.count++;
            acc.set(name, a);
          }
          this.reports.set([...acc].map(([manufacturer, a]) => ({ manufacturer, rating: a.sum / a.count })));
        },
        error: () => this.messages.error('Error retrieving reports'),
      }),
    });
  }
}
